import gurobipy as gp
from gurobipy import GRB
tablet_records = [rec for rec in LEGACY_RECORDS if rec['values'].get('Product Name', '').startswith('TABLET')]
product_names = []
revenue = {}
demand = {}
inventory = {}
for rec in tablet_records:
    vals = rec['values']
    name = vals['Product Name']
    product_names.append(name)
    try:
        revenue[name] = float(vals['Revenue'])
        demand[name] = int(vals['Demand'])
        inventory[name] = int(vals['Initial Inventory'])
    except Exception as e:
        raise ValueError(f'Missing or invalid data for product {name}: {e}')
for name in product_names:
    if name not in revenue or name not in demand or name not in inventory:
        raise ValueError(f'Missing data for product {name}')
m = gp.Model('SmartphoneRetailOutlet_TABLET')
x_vars = m.addVars(product_names, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((revenue[name] * x_vars[name] for name in product_names)), GRB.MAXIMIZE)
m.addConstrs((x_vars[name] <= demand[name] for name in product_names), name='')
m.addConstrs((x_vars[name] <= inventory[name] for name in product_names), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
